import sys

def main():
    s = sys.stdin.read().split()[0]
    r = s[::-1]
    cnt = {}
    for ch in s:
        cnt[ch] = cnt.get(ch, 0) + 1
    seen = set()
    dedup = []
    reps = []
    for ch in r:
        if ch not in seen:
            seen.add(ch)
            dedup.append(ch)
            if cnt[ch] > 1:
                reps.append(ch + '=' + str(cnt[ch]))
    print(r)
    print(''.join(dedup))
    print(' '.join(reps) if reps else 'none')

